package net.gijun.collector.ui.icons

import androidx.compose.ui.graphics.Color
import androidx.compose.ui.graphics.SolidColor
import androidx.compose.ui.graphics.vector.ImageVector
import androidx.compose.ui.graphics.vector.addPathNodes
import androidx.compose.ui.unit.dp

/**
 * 이 앱이 실제로 쓰는 Material 아이콘 30개만 담은 자체 아이콘 세트.
 *
 * compose.materialIconsExtended 의존성은 36.8MB짜리 jar 하나로, 라이브러리 전체
 * 아이콘(2천여 개)의 ImageVector 를 코드로 들고 있다. 우리가 쓰는 건 30개뿐이라
 * MSI 용량의 3분의 1을 안 쓰는 아이콘이 차지하고 있었다. 그래서 의존성을 걷어내고
 * 필요한 것만 SVG path 문자열로 옮겼다.
 *
 * path 데이터는 Material Design Icons(Apache-2.0) filled 스타일 24dp 원본 그대로다.
 * 아이콘을 추가할 때는 같은 출처의 24x24 SVG 에서 `d` 속성을 그대로 가져오면 된다.
 *
 * ImageVector 는 by lazy 로 최초 사용 시점에 한 번만 만든다. 매 컴포지션마다
 * path 를 다시 파싱하면 안 되기 때문이다.
 */
object AppIcons {

    private fun build(name: String, pathData: String): ImageVector =
        ImageVector.Builder(
            name = name,
            defaultWidth = 24.dp,
            defaultHeight = 24.dp,
            viewportWidth = 24f,
            viewportHeight = 24f,
        ).apply {
            addPath(
                pathData = addPathNodes(pathData),
                fill = SolidColor(Color.Black),
            )
        }.build()

